ALTER TABLE "payment_review_case" ADD CONSTRAINT "payment_review_case_dashboard_refund_settled" CHECK ("payment_review_case"."dashboard_refund_reference" IS NULL OR (NOT "payment_review_case"."refund_due" AND "payment_review_case"."resolved_at" IS NOT NULL AND "payment_review_case"."outcome" IN ('refund', 'confirm') AND "payment_review_case"."currency" <> 'INR' AND "payment_review_case"."gateway_payment_id" IS NOT NULL AND "payment_review_case"."amount_minor" > 0));